-- Run in the application database. Use this OR the Laravel migration, not both.
-- All DATETIME values are UTC. UUIDs are generated by the application.
CREATE TABLE chatbot_query_logs (
    id VARCHAR(36) NOT NULL PRIMARY KEY,
    user_id BIGINT UNSIGNED NOT NULL,
    conversation_id VARCHAR(36) NULL,
    scope VARCHAR(32) NULL,
    cohort_id VARCHAR(255) NULL,
    started_at DATETIME NOT NULL,
    completed_at DATETIME NULL,
    duration_ms BIGINT UNSIGNED NULL,
    status VARCHAR(24) NOT NULL,
    provider VARCHAR(128) NULL,
    model VARCHAR(255) NULL,
    question LONGTEXT NULL,
    answer LONGTEXT NULL,
    tools_json LONGTEXT NULL,
    llm_calls_json LONGTEXT NULL,
    feedback LONGTEXT NULL,
    input_tokens BIGINT UNSIGNED NULL,
    output_tokens BIGINT UNSIGNED NULL,
    total_tokens BIGINT UNSIGNED NULL,
    cache_read_tokens BIGINT UNSIGNED NULL,
    cache_write_tokens BIGINT UNSIGNED NULL,
    reasoning_tokens BIGINT UNSIGNED NULL,
    usage_status VARCHAR(24) NOT NULL DEFAULT 'unavailable',
    rating TINYINT UNSIGNED NULL,
    feedback_at DATETIME NULL,
    CONSTRAINT chatlog_rating_check CHECK (rating BETWEEN 1 AND 5),
    INDEX chatlog_started_idx (started_at),
    INDEX chatlog_user_idx (user_id, started_at),
    INDEX chatlog_rating_idx (rating, started_at),
    INDEX chatlog_status_idx (status, started_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
